1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { z } from "zod";
5	import { db } from "./db";
6	import { requireUser } from "./auth";
7	import { InsufficientBalanceError } from "./wallet";
8	import { resizeQuote, applyResize, ResizeError } from "./resize";
9	import { createResizeCheckout } from "./stripe";
10	import { walletSplit } from "./wallet-split";
11	
12	async function ownedServer(serverId: string) {
13	  const user = await requireUser();
14	  const server = await db.server.findUnique({ where: { id: serverId }, include: { plan: true } });
15	  if (!server) throw new Error("Not found");
16	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
17	  return { user, server };
18	}
19	
20	async function queueJob(
21	  serverId: string,
22	  type:
23	    | "SNAPSHOT_CREATE"
24	    | "SNAPSHOT_DELETE"
25	    | "SNAPSHOT_ROLLBACK"
26	    | "BACKUP_CREATE"
27	    | "RESIZE"
28	    | "PASSWORD_RESET",
29	  payload?: Record<string, unknown>
30	): Promise<{ error?: string }> {
31	  const pending = await db.job.count({
32	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
33	  });
34	  if (pending > 0) return { error: "Another operation is already in progress on this server." };
35	  await db.job.create({ data: { type, serverId, payload: payload as any } });
36	  return {};
37	}
38	
39	// ---------- Snapshots ----------
40	
41	export async function createSnapshot(serverId: string, name: string): Promise<{ error?: string }> {
42	  const { user, server } = await ownedServer(serverId);
43	  const clean = name.replace(/[^a-zA-Z0-9_]/g, "").slice(0, 40);
44	  if (clean.length < 2) return { error: "Snapshot name: letters, digits, underscores (min 2)." };
45	  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
46	    return { error: "Server must be running or stopped." };
47	  }
48	  const res = await queueJob(serverId, "SNAPSHOT_CREATE", { name: clean });
49	  if (!res.error) {
50	    await db.auditLog.create({ data: { userId: user.id, action: "server.snapshot_create", detail: `${serverId} ${clean}` } });
51	    revalidatePath(`/dashboard/servers/${serverId}`);
52	  }
53	  return res;
54	}
55	
56	export async function deleteSnapshot(serverId: string, name: string): Promise<{ error?: string }> {
57	  const { user } = await ownedServer(serverId);
58	  const res = await queueJob(serverId, "SNAPSHOT_DELETE", { name });
59	  if (!res.error) {
60	    await db.auditLog.create({ data: { userId: user.id, action: "server.snapshot_delete", detail: `${serverId} ${name}` } });
61	    revalidatePath(`/dashboard/servers/${serverId}`);
62	  }
63	  return res;
64	}
65	
66	export async function rollbackSnapshot(serverId: string, name: string): Promise<{ error?: string }> {
67	  const { user } = await ownedServer(serverId);
68	  const res = await queueJob(serverId, "SNAPSHOT_ROLLBACK", { name });
69	  if (!res.error) {
70	    await db.auditLog.create({ data: { userId: user.id, action: "server.snapshot_rollback", detail: `${serverId} ${name}` } });
71	    revalidatePath(`/dashboard/servers/${serverId}`);
72	  }
73	  return res;
74	}
75	
76	// ---------- Backups ----------
77	
78	export async function createBackup(serverId: string): Promise<{ error?: string }> {
79	  const { user, server } = await ownedServer(serverId);
80	  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
81	    return { error: "Server must be running or stopped." };
82	  }
83	  const res = await queueJob(serverId, "BACKUP_CREATE");
84	  if (!res.error) {
85	    await db.auditLog.create({ data: { userId: user.id, action: "server.backup_create", detail: serverId } });
86	    revalidatePath(`/dashboard/servers/${serverId}`);
87	  }
88	  return res;
89	}
90	
91	export type BackupJobStatus = {
92	  id: string;
93	  type: "BACKUP_CREATE" | "BACKUP_RESTORE";
94	  status: "QUEUED" | "RUNNING" | "DONE" | "FAILED";
95	  progress: number;
96	  step: string | null;
97	  error: string | null;
98	  createdAt: string;
99	};
100	
101	/**
102	 * Return the most recent backup/restore job for a server so the UI can render a
103	 * live progress bar. Ownership-checked. Returns null if the server has never had
104	 * a backup/restore job. The client decides when to show the bar (in-flight) vs.
105	 * the completion/failure note.
106	 */
107	export async function getBackupJob(serverId: string): Promise<BackupJobStatus | null> {
108	  const { server } = await ownedServer(serverId);
109	  const job = await db.job.findFirst({
110	    where: { serverId: server.id, type: { in: ["BACKUP_CREATE", "BACKUP_RESTORE"] } },
111	    orderBy: { createdAt: "desc" },
112	    select: { id: true, type: true, status: true, progress: true, step: true, error: true, createdAt: true },
113	  });
114	  if (!job) return null;
115	  return {
116	    id: job.id,
117	    type: job.type as BackupJobStatus["type"],
118	    status: job.status as BackupJobStatus["status"],
119	    progress: job.progress,
120	    step: job.step,
121	    error: job.error,
122	    createdAt: job.createdAt.toISOString(),
123	  };
124	}
