126	// ---------- Resize ----------
127	
128	export async function resizeServer(
129	  serverId: string,
130	  planId: string,
131	  useWallet: boolean = true,
132	): Promise<{ error?: string; checkoutUrl?: string }> {
133	  const { user, server } = await ownedServer(serverId);
134	
135	  // Validate + price the upgrade (ownership already checked above). resizeQuote
136	  // recomputes the exact prorated charge over the remaining term.
137	  let quote;
138	  try {
139	    quote = await resizeQuote(serverId, planId);
140	  } catch (e) {
141	    if (e instanceof ResizeError) return { error: e.message };
142	    throw e;
143	  }
144	  const { newPlan, prorateCents } = quote;
145	
146	  // Wallet-aware split — identical logic to the deploy flow. ResizePicker computes
147	  // the same split (lib/wallet-split.ts) so displayed === charged.
148	  const { cardCents } = walletSplit({
149	    dueCents: prorateCents,
150	    balanceCents: user.balanceCents,
151	    useWallet,
152	  });
153	
154	  // Card portion > 0 → charge ONLY the remainder on the card (not the full
155	  // proration). The confirm route credits the card amount to the wallet and then
156	  // debits the FULL proration (encoded as chargeCents), so the wallet absorbs its
157	  // share and the card the rest — wallet never touched before the card clears.
158	  if (cardCents > 0) {
159	    const url = await createResizeCheckout(user, cardCents, {
160	      serverId,
161	      planId,
162	      planName: newPlan.name,
163	      prorateCents,
164	    });
165	    if (!url) {
166	      return {
167	        error: `Upgrading costs $${(prorateCents / 100).toFixed(2)} for the rest of your term, and card payments aren't set up — top up your wallet first.`,
168	      };
169	    }
170	    return { checkoutUrl: url };
171	  }
172	
173	  // Card portion is $0 (wallet fully covers it, or the charge is $0 for free/admin
174	  // servers) → apply instantly, debiting the full proration from the wallet.
175	  try {
176	    await applyResize({ serverId, planId, actorUserId: user.id });
177	  } catch (e) {
178	    if (e instanceof ResizeError) return { error: e.message };
179	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
180	    throw e;
181	  }
182	  revalidatePath(`/dashboard/servers/${serverId}`);
183	  return {};
184	}
