186	// ---------- Root password reset ----------
187	
188	export async function resetRootPassword(serverId: string): Promise<{ error?: string }> {
189	  const { user, server } = await ownedServer(serverId);
190	  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
191	    return { error: "Server must be running or stopped to reset its password." };
192	  }
193	  const res = await queueJob(serverId, "PASSWORD_RESET");
194	  if (!res.error) {
195	    await db.auditLog.create({
196	      data: { userId: user.id, action: "server.password_reset", detail: serverId },
197	    });
198	    revalidatePath(`/dashboard/servers/${serverId}`);
199	    revalidatePath(`/admin/servers/${serverId}`);
200	  }
201	  return res;
202	}
