254	      const tpl = emails.receipt(`$${(cents / 100).toFixed(2)}`, "wallet top-up");
255	      await sendMail({ to: u.email, subject: tpl.subject, html: tpl.html });
256	    }
257	  } catch { /* best-effort */ }
258	  return true;
259	}
