1	// Shared server-upgrade (RESIZE up) core — used by the wallet flow
2	// (lib/actions-server.ts resizeServer) and by the Stripe confirm route so a paid
3	// checkout can apply the upgrade immediately. Plain server module (not "use server").
4	import { db } from "./db";
5	import { debitWallet, InsufficientBalanceError } from "./wallet";
6	import { invoiceCreateData } from "./invoices";
7	
8	/** Average calendar month in ms (365.25/12 ≈ 30.44d) for duration-based proration. */
9	export const MS_PER_AVG_MONTH = 30.44 * 86400_000;
10	
11	export class ResizeError extends Error {}
12	
13	type QuotedServer = Awaited<ReturnType<typeof loadServer>>;
14	type QuotedPlan = NonNullable<Awaited<ReturnType<typeof loadPlan>>>;
15	
16	function loadServer(serverId: string) {
17	  return db.server.findUnique({ where: { id: serverId }, include: { plan: true } });
18	}
19	function loadPlan(planId: string) {
20	  return db.plan.findUnique({ where: { id: planId } });
21	}
22	
23	export type ResizeQuote = {
24	  server: NonNullable<QuotedServer>;
25	  newPlan: QuotedPlan;
26	  prorateCents: number;
27	};
28	
29	/**
30	 * Validate an UPGRADE and compute the prorated charge over the ACTUAL remaining
31	 * duration (monthly price difference for every remaining month; null expiresAt
32	 * on free/admin servers => 0). Throws ResizeError with a user-facing message on
33	 * any guard failure. Does NOT check ownership — callers must do that.
34	 *
35	 * ─── INTERACTION WITH PER-SERVER EXTRA DISK ─────────────────────────────────
36	 * `Server.extraDiskGB` (disk bought via the deploy upsell or "Add storage") is
37	 * ADDITIVE to whichever plan the server is on, so a plan change must leave it
38	 * completely alone. Two things follow, and both are deliberate:
39	 *
40	 *  1. NOT DOUBLE-CHARGED. The proration below is a difference of PLAN monthly
41	 *     prices. The extra-disk surcharge is identical before and after the resize
42	 *     (same GB, same per-GB price), so it cancels out of the delta exactly — it
43	 *     must never be added here. It keeps being billed, unchanged, by the renewal
44	 *     sweep, which reads `extraDiskGB` directly.
45	 *  2. NOT LOST. Nothing in the resize path writes `extraDiskGB`, and the worker's
46	 *     RESIZE handler sizes the disk to `newPlan.diskGB + server.extraDiskGB` — so
47	 *     the customer keeps every GB they paid for. (Sizing to the bare plan disk
48	 *     would ask Proxmox to SHRINK the disk of any server holding extra storage,
49	 *     and the whole resize would hard-fail.)
50	 *
51	 * The disk-grow guard below intentionally compares PLAN disks, not effective
52	 * disks: since the extra is added to both sides, a target plan with an equal or
53	 * larger disk can never shrink the effective disk.
54	 */
55	export async function resizeQuote(serverId: string, planId: string): Promise<ResizeQuote> {
56	  const server = await loadServer(serverId);
57	  if (!server) throw new ResizeError("Not found");
58	  const newPlan = await loadPlan(planId);
59	  if (!newPlan?.active) throw new ResizeError("Plan not available.");
60	  if (newPlan.id === server.planId) throw new ResizeError("Server is already on this plan.");
61	  if (newPlan.diskGB < server.plan.diskGB) {
62	    throw new ResizeError("Disk storage can only grow — choose a plan with equal or larger disk.");
63	  }
64	  if (newPlan.priceCents < server.plan.priceCents) {
65	    throw new ResizeError("Downgrades aren't self-service yet — please contact support.");
66	  }
67	  if (!["RUNNING", "STOPPED"].includes(server.status)) throw new ResizeError("Server is busy.");
68	
69	  let prorateCents = 0;
70	  if (!server.isFree && server.expiresAt) {
71	    const now = Date.now();
72	    const remainingMonths = Math.max(0, (server.expiresAt.getTime() - now) / MS_PER_AVG_MONTH);
73	    const monthlyDelta = newPlan.priceCents - server.plan.priceCents; // plan.priceCents is the monthly price
74	    prorateCents = Math.max(0, Math.round(monthlyDelta * remainingMonths));
75	  }
76	  return { server, newPlan, prorateCents };
77	}
78	
79	/**
80	 * Apply the upgrade: (optionally) debit the wallet for the prorated charge, record
81	 * the wallet transaction + PAID invoice, and queue the RESIZE job that the worker
82	 * performs on Proxmox. Re-validates every guard (plan availability, disk-grow,
83	 * not a downgrade, steady state, one in-flight job) so it is safe to call from the
84	 * unauthenticated confirm route. Throws ResizeError on any guard failure.
85	 *
86	 * `chargeCents` overrides the recomputed proration — the paid path passes the exact
87	 * amount the customer paid into their wallet at checkout so the debit here nets to
88	 * zero against that credit (mirrors how the deploy confirm re-runs placeOrder to
89	 * spend the just-credited funds). The wallet path omits it and debits the quote.
90	 */
91	export async function applyResize(opts: {
92	  serverId: string;
93	  planId: string;
94	  actorUserId: string;
95	  chargeCents?: number;
96	}): Promise<void> {
97	  const { server, newPlan, prorateCents: quoted } = await resizeQuote(opts.serverId, opts.planId);
98	  const prorateCents = opts.chargeCents ?? quoted;
99	
100	  const pending = await db.job.count({ where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } } });
101	  if (pending > 0) throw new ResizeError("Another operation is already in progress on this server.");
102	
103	  try {
104	    await db.$transaction(async (tx) => {
105	      if (prorateCents > 0) {
106	        await debitWallet(tx, server.userId, prorateCents);
107	        await tx.walletTransaction.create({
108	          data: {
109	            userId: server.userId,
110	            amountCents: -prorateCents,
111	            description: `Upgrade to ${newPlan.name} (prorated) — ${server.hostname}`,
112	          },
113	        });
114	        // PAID invoice for the proration charge (one per user-initiated resize).
115	        await tx.invoice.create({
116	          data: invoiceCreateData({
117	            userId: server.userId,
118	            description: `Upgrade to ${newPlan.name} (prorated) — ${server.hostname}`,
119	            status: "PAID",
120	            lineItems: [
121	              { description: `Upgrade to ${newPlan.name} — prorated for remaining term (${server.hostname})`, qty: 1, unitCents: prorateCents, amountCents: prorateCents },
122	            ],
123	          }),
124	        });
125	      }
126	      // Record the amount charged on the job so the worker's RESIZE handler can
127	      // REVERSE it (credit `payload.prorateCents` back to the wallet) if the
128	      // resize terminally fails — money is committed here, before the job runs.
129	      await tx.job.create({
130	        data: { type: "RESIZE", serverId: server.id, payload: { planId: opts.planId, prorateCents, direction: "up" } as any },
131	      });
132	      await tx.auditLog.create({
133	        data: { userId: opts.actorUserId, action: "server.resize", detail: `${server.id} -> ${newPlan.slug} prorate=${prorateCents}` },
134	      });
135	    });
136	  } catch (e) {
137	    if (e instanceof InsufficientBalanceError) throw new ResizeError("Insufficient balance — top up your wallet first.");
138	    throw e;
139	  }
140	}
