/**
 * Validate a promo code for the CURRENT user against a top-up of `baseCents` and
 * return the bonus that would be credited. Read-only: it never mutates state,
 * so it is safe to call both for the live preview (CouponField) and again inside
 * `topUp` to compute the real bonus. Enforces active / expiry / scope /
 * minAmount / maxRedemptions / firstTimeOnly / one-per-user rules.
 */
export async function applyCouponToTopup(
  code: string,
  baseCents: number
): Promise<CouponApplyResult> {
  const user = await requireUser();
  // Global kill-switch: when coupons are disabled no code may be redeemed.
  // Checked here so both the live preview and the real `topUp` apply are covered.
  if (!(await getSettingBool("coupons_enabled", true))) {
    return { ok: false, error: "Promo codes are currently disabled." };
  }
  const normalized = String(code ?? "").trim().toUpperCase();
  if (!normalized) return { ok: false, error: "Enter a promo code." };

  const coupon = await db.coupon.findUnique({ where: { code: normalized } });
  if (!coupon || !coupon.active) return { ok: false, error: "That code isn’t valid." };
  if (coupon.scope === "ORDER") {
    return { ok: false, error: "This code only applies to server orders." };
  }
  if (coupon.expiresAt && coupon.expiresAt.getTime() < Date.now()) {
    return { ok: false, error: "This code has expired." };
  }
  if (coupon.maxRedemptions !== null && coupon.timesRedeemed >= coupon.maxRedemptions) {
    return { ok: false, error: "This code has reached its redemption limit." };
  }
  if (coupon.minAmountCents !== null && baseCents < coupon.minAmountCents) {
    return {
      ok: false,
      error: `Add at least $${(coupon.minAmountCents / 100).toFixed(2)} to use this code.`,
    };
  }

  // One redemption per user (mirrors the @@unique([couponId,userId]) constraint).
  const already = await db.couponRedemption.findUnique({
    where: { couponId_userId: { couponId: coupon.id, userId: user.id } },
  });
  if (already) return { ok: false, error: "You’ve already used this code." };

  if (coupon.firstTimeOnly) {
    // "First-time" = the user has never received a positive wallet credit before.
    const priorCredits = await db.walletTransaction.count({
      where: { userId: user.id, amountCents: { gt: 0 } },
    });
    if (priorCredits > 0) {
      return { ok: false, error: "This code is for first-time customers only." };
    }
  }

  const bonusCents = Math.max(0, couponBonusForTopup(coupon, baseCents));
  return {
    ok: true,
    couponId: coupon.id,
    code: coupon.code,
    bonusCents,
    label: describeCoupon(coupon),
  };
}

